module longest_alternating_subsequence(\n    input [4:0] n,\n    input [15:0] s,\n    output reg [4:0] result\n);\n    integer i;\n    reg [4:0] changes;\n\n    always @(*) begin\n        changes = 5'd0;\n        for (i = 0; i < 15; i = i + 1) begin\n            if (i < n - 1) begin\n                if (s[i] != s[i + 1])\n                    changes = changes + 5'd1;\n            end\n        end\n        if (changes + 5'd3 > n)\n            result = n;\n        else\n            result = changes + 5'd3;\n    end\nendmodule